// VALIDATE SCOUT SETUP
// Stops the run before Find Existing Row, and therefore before any Notion
// request, when configuration is missing. Without this an unconfigured
// instance would build a query URL with an empty database id and fail deep in
// an HTTP node instead of naming the field to fix.
const cfg = $('Scout Setup').first().json;
const problems = [];

const databaseId = (cfg.notionDatabaseId || '').toString().trim();
if (!databaseId) {
  problems.push('notionDatabaseId is empty. Paste the id of your Notion signal map database.');
}

if (problems.length > 0) {
  throw new Error('Scout Setup is not configured correctly. ' + problems.join(' '));
}

return [{ json: { validated: true } }];

// PARSE HUBSPOT COMMUNITY NOTIFICATION EMAILS
// Notification templates change and Gmail exposes the body under several
// different field names, so this builds one haystack from every text-ish field
// present and looks for a community topic link. Messages without one are
// dropped: this workflow only reacts to community threads.
//
// Sender addresses are deliberately never carried forward. Scout keeps the
// public display name and the topic URL and nothing else about the person.
//
// Messages are read from the trigger by name rather than from $input, because
// Validate Setup sits between the trigger and this node.
const TOPIC_URL_RE = /https?:\/\/community\.hubspot\.com\/t\/[a-z0-9-]+\/(\d+)/i;
const ADDRESS_RE = /[^\s<>()"']+@[^\s<>()"']+\.[^\s<>()"']+/g;
const REPLIER_RE = /([A-Za-z0-9_.\- ]{2,40})\s+(?:replied|posted|responded|mentioned)/i;

function scrub(value) {
  return (value === null || value === undefined ? '' : String(value)).replace(ADDRESS_RE, '[address removed]');
}

const out = [];

for (const item of $('Community Notifications').all()) {
  const mail = item.json || {};
  const haystack = [mail.text, mail.html, mail.textHtml, mail.textPlain, mail.snippet, mail.subject, mail.Subject, mail.body]
    .filter(Boolean)
    .join('\n');

  const match = haystack.match(TOPIC_URL_RE);
  if (!match) continue;

  const replierMatch = scrub(haystack).match(REPLIER_RE);

  // Only two values leave this node: the topic link, which is public, and a
  // display name derived from it. The subject, snippet, body, Gmail message id
  // and sender address are read to find those two and are then discarded here,
  // so no later node can put them in a Notion request even by accident.
  out.push({ json: {
    topicUrl: match[0],
    topicId: match[1],
    replier: replierMatch ? replierMatch[1].trim() : ''
  }});
}

return out;

// DECIDE: UPDATE THE MATCHED ROW, OR CREATE A NEW ENGAGEMENT ROW
// Notion responses arrive in the same order the notifications were sent, so
// each response is paired with its notification by index. One item carries the
// method, URL and body, which lets a single HTTP node handle both PATCH and
// POST.
const DATABASE_ID = ($('Scout Setup').first().json.notionDatabaseId || '').toString().trim();
const today = new Date(+$now).toISOString().slice(0, 10);

function cap(value) {
  return (value === null || value === undefined ? '' : String(value)).slice(0, 1900);
}

const sources = $('Parse Notification').all();
const inputs = $input.all();
const out = [];

for (let i = 0; i < inputs.length; i++) {
  const response = inputs[i].json || {};
  const src = (sources[i] && sources[i].json) || {};
  const results = Array.isArray(response.results) ? response.results : [];

  if (results.length > 0) {
    // Someone already in the signal map replied. Advance the existing row
    // instead of creating a duplicate.
    out.push({ json: {
      matched: true,
      topicUrl: src.topicUrl,
      _method: 'PATCH',
      _url: 'https://api.notion.com/v1/pages/' + results[0].id,
      _notionBody: { properties: {
        'Replied': { checkbox: true },
        'Status': { select: { name: 'In conversation' } },
        'Next action': { select: { name: 'DM' } },
        'Last touch': { date: { start: today } }
      }}
    }});
    continue;
  }

  // Someone new engaged on a thread you are already in. That is a warm signal,
  // so it gets its own row. There is no classifier on this path, so persona
  // and track stay Unknown until a human or workflow 05 fills them in.
  //
  // The row is built from the parsed display name and the topic link only.
  // Falling back to the email subject would have put mail content into Notion,
  // so an unrecognised name falls back to a fixed neutral label instead, and
  // Signal is a constant rather than anything quoted from the message.
  const name = (src.replier && src.replier.trim()) || 'HubSpot Community participant';

  out.push({ json: {
    matched: false,
    topicUrl: src.topicUrl,
    _method: 'POST',
    _url: 'https://api.notion.com/v1/pages',
    _notionBody: { parent: { database_id: DATABASE_ID }, properties: {
      'Name': { title: [{ text: { content: cap(name) } }] },
      'Signal': { rich_text: [{ text: { content: 'Inbound HubSpot Community engagement' } }] },
      'Evidence': { rich_text: [{ text: { content: 'Replied on a community thread you are in, seen through an email notification.' } }] },
      'Warmth tier': { select: { name: 'Tier 1 (hot)' } },
      'Persona type': { select: { name: 'Unknown' } },
      'Track': { select: { name: 'Unknown' } },
      'Source': { select: { name: 'HubSpot Community' } },
      'Source URL': { url: src.topicUrl || null },
      'Status': { select: { name: 'Engaged' } },
      'Next action': { select: { name: 'DM' } },
      'Replied': { checkbox: true },
      'Last touch': { date: { start: today } }
    }}
  }});
}

return out;
